.fail{background:#fff1f2;color:#ad2633;border-color:#f1c5ca}.rac-validation-result h3{font-size:1.05rem;margin:.6rem 0 .2rem}.rac-validation-result p{font-size:.72rem;margin:0}.rac-final-check{height:100%;padding:1.2rem;border-radius:12px;background:linear-gradient(145deg,#eef6ff,#fff);border:1px solid #cfe0f5}.rac-final-check>i{font-size:2rem;color:var(--blue)}.rac-final-check h3{font-size:1rem;color:var(--navy);margin:.6rem 0}.rac-final-check p,.rac-final-check li{font-size:.73rem;color:#63748a}.rac-confirm{max-width:720px;margin:3.2rem auto 1rem;text-align:center;background:#fff;border:1px solid var(--line);border-radius:17px;padding:2rem;box-shadow:0 15px 40px rgba(8,48,95,.12)}.rac-success{width:75px;height:75px;border-radius:50%;display:grid;place-items:center;background:#149252;color:#fff;font-size:2rem;margin:-4rem auto 1rem;border:7px solid #edf9f2}.rac-confirm h2{font-size:1.35rem;color:var(--navy);font-weight:800}.rac-confirm>p{font-size:.8rem;color:#6d7d91}.rac-confirm-card{background:#f2f7fd;border:1px solid #d7e4f4;border-radius:10px;padding:1rem;text-align:left}.rac-next{display:flex;gap:.7rem;text-align:left;margin-top:1rem;background:#eaf4ff;color:#245c99;border-radius:9px;padding:.75rem}.rac-next p{font-size:.72rem;margin:.1rem 0}.rac-overlay{position:fixed;inset:0;background:rgba(5,22,46,.6);z-index:1085;display:grid;place-items:center;padding:1rem}.rac-dialog{width:min(760px,100%);max-height:80vh;background:#fff;border-radius:14px;overflow:hidden}.rac-dialog-head{display:flex;justify-content:space-between;padding:1rem;border-bottom:1px solid var(--line)}.rac-dialog-head h2{font-size:1.05rem;color:var(--navy);margin:0}.rac-dialog-head p{font-size:.7rem;color:#748398;margin:.15rem 0}.rac-history{padding:1rem;max-height:60vh;overflow:auto}@media(max-width:991px){.rac-metrics{grid-template-columns:repeat(2,1fr)}}@media(max-width:767px){.rac-heading{align-items:flex-start;flex-direction:column}.rac-tools{width:100%}.rac-tools .btn{flex:1}.rac-metrics{grid-template-columns:1fr 1fr}.rac-filterbar>*{width:100%}.rac-actions{flex-wrap:wrap}.rac-actions .ms-auto{margin-left:0!important;width:100%}.rac-request{align-items:flex-start;flex-wrap:wrap}.rac-request button{margin-left:0}.rac-dl{grid-template-columns:95px 1fr}}@media print{body *{visibility:hidden}.rac-shell,.rac-shell *{visibility:visible}.rac-shell{position:absolute;inset:0}.rac-heading,.rac-connections,.rac-step-card,.rac-tools,.rac-actions,.btn,.rac-overlay{display:none!important}.rac-page{display:none!important}.rac-page[data-page="7"]{display:block!important}.main-content{margin:0!important}}
.rac-overlay.d-none{display:none!important}
</style>

<script>
(()=>{'use strict';
const BASE=<?= json_encode(BASE_URL,JSON_UNESCAPED_SLASHES) ?>,API=BASE+'/api/scheduling/room-availability.php',PREFILL={type:<?= json_encode($prefillType) ?>,id:<?= $prefillId ?>};
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const S={page:1,max:1,data:null,request:null,criteria:null,results:[],room:null,validation:null,assignment:null};
function alertMsg(m){$('racAlert').classList.toggle('d-none',!m);$('racAlert').querySelector('span').textContent=m||'';if(m)scrollTo({top:0,behavior:'smooth'})}
async function api(url,opt={}){const r=await fetch(url,{credentials:'same-origin',headers:{'Accept':'application/json','Content-Type':'application/json'},...opt});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Request failed.');return d}
function go(n){if(n>S.max)return;S.page=n;document.querySelectorAll('.rac-page').forEach(x=>x.classList.toggle('d-none',+x.dataset.page!==n));document.querySelectorAll('#racSteps li').forEach((x,i)=>{x.classList.toggle('active',i+1===n);x.classList.toggle('done',i+1<n)});alertMsg('');scrollTo({top:0,behavior:'smooth'})}
function unlock(n){S.max=Math.max(S.max,n);go(n)}
function badge(text){const c={Available:'green',Occupied:'red',Reserved:'purple',Maintenance:'amber',Unavailable:'gray',Draft:'amber',Validated:'green',Scheduled:'blue','Ready to Publish':'green'}[text]||'blue';return `<span class="rac-badge ${c}">${esc(text)}</span>`}
function fmtDate(v){if(!v)return'—';return new Date(v+'T00:00:00').toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'})}
function dl(items){return `<dl class="rac-dl">${items.map(x=>`<dt>${esc(x[0])}</dt><dd>${x[2]?x[1]:esc(x[1]??'—')}</dd>`).join('')}</dl>`}
function sourceIcon(t){return t==='Regular'?'user-cog':t==='Special'?'calendar-plus':'calendar-stats'}
function nextDate(day){const days=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'],d=new Date();let add=(days.indexOf(day)-d.getDay()+7)%7;if(!add)add=7;d.setDate(d.getDate()+add);return d.toISOString().slice(0,10)}
function renderMetrics(s){const cards=[['total','building-community','Total Rooms'],['available','circle-check','Available'],['occupied','users','Occupied'],['reserved','calendar-clock','Reserved'],['maintenance','tools','Maintenance']];$('racMetrics').innerHTML=cards.map(x=>`<div class="rac-metric ${x[0]}"><i class="ti ti-${x[1]}"></i><div><b>${s[x[0]]||0}</b><small>${x[2]}</small></div></div>`).join('')}
function renderRequests(){const type=$('dashType').value,year=$('dashYear').value,sem=$('dashSemester').value;const rows=(S.data.requests||[]).filter(r=>(!type||r.source_type===type)&&(!year||r.academic_year===year)&&(!sem||r.semester===sem));$('requestRows').innerHTML=rows.length?rows.map(r=>`<tr><td><i class="ti ti-${sourceIcon(r.source_type)} me-1 text-primary"></i>${esc(r.source_type)}</td><td><b>${esc(r.title)}</b><br><small>${esc(r.faculty_name||'Faculty not assigned')}</small></td><td>${esc(r.section_code)}</td><td>${esc(r.day_of_week)}<br><small>${esc(r.start_time)}–${esc(r.end_time)}</small></td><td>${esc(r.room_code||'Unassigned')}</td><td>${badge(r.status)}</td><td><button class="btn btn-sm btn-primary" data-request="${r.source_type}:${r.id}"><i class="ti ti-arrow-right"></i></button></td></tr>`).join(''):`<tr><td colspan="7" class="rac-empty"><i class="ti ti-inbox-off d-block fs-3 mb-2"></i>No scheduling requests match these filters.</td></tr>`}
function renderRecent(){const h=S.data.history||[];$('recentHistory').innerHTML=h.length?h.map(x=>`<div class="rac-activity-item"><b><i class="ti ti-door-enter me-1"></i>${esc(x.assigned_room)} assigned</b><p>${esc(x.source_type)} schedule #${x.source_record_id}${x.previous_room?' · replaced '+esc(x.previous_room):''}</p><small>${esc(x.assigned_by)} · ${esc(x.assigned_at)}</small></div>`).join(''):`<div class="rac-empty"><i class="ti ti-history-off d-block fs-3 mb-2"></i>No room assignments recorded yet.</div>`}
function fillOptions(){const o=S.data.options;for(const [id,vals] of [['reqBuilding',o.buildings],['reqType',o.room_types]])vals.forEach(v=>$(id).insertAdjacentHTML('beforeend',`<option>${esc(v)}</option>`));$('reqFacilities').innerHTML=o.facilities.length?o.facilities.map(v=>`<option>${esc(v)}</option>`).join(''):'<option disabled>No facilities configured</option>';const years=[...new Set(o.terms.map(t=>t.academic_year))],sems=[...new Set(o.terms.map(t=>t.semester))];years.forEach(v=>$('dashYear').insertAdjacentHTML('beforeend',`<option>${esc(v)}</option>`));sems.forEach(v=>$('dashSemester').insertAdjacentHTML('beforeend',`<option>${esc(v)}</option>`))}
function chooseRequest(r){S.request=r;$('selectedRequest').innerHTML=`<i class="ti ti-${sourceIcon(r.source_type)}"></i><div><b>${esc(r.title)} · ${esc(r.section_code)}</b><p>${esc(r.source_type)} · ${esc(r.faculty_name||'Faculty unassigned')} · ${esc(r.academic_year)} ${esc(r.semester)} · current room: ${esc(r.room_code||'Unassigned')}</p></div><button class="btn btn-sm btn-outline-primary" id="changeRequest">Change</button>`;$('changeRequest').onclick=()=>go(1);$('reqDate').value=r.schedule_date||nextDate(r.day_of_week);$('reqDay').value=new Date($('reqDate').value+'T00:00:00').toLocaleDateString('en-US',{weekday:'long'});$('reqStart').value=r.start_time;$('reqEnd').value=r.end_time;$('reqStart').readOnly=true;$('reqEnd').readOnly=true;$('reqCapacity').value=r.participant_count||0;if(r.class_type==='Laboratory')$('reqType').value='Laboratory';else if(r.class_type==='Lecture')$('reqType').value='Lecture';unlock(2)}
function manual(){S.request=null;$('selectedRequest').innerHTML='<i class="ti ti-info-circle"></i><div><b>Availability browsing mode</b><p>Select a linked request before attempting to save a room assignment.</p></div><button class="btn btn-sm btn-outline-primary" id="changeRequest">Choose Request</button>';$('changeRequest').onclick=()=>go(1);$('reqStart').readOnly=false;$('reqEnd').readOnly=false;unlock(2)}
function params(action='search'){const p=new URLSearchParams({action,date:$('reqDate').value,start:$('reqStart').value,end:$('reqEnd').value,building:$('reqBuilding').value,room_type:$('reqType').value,capacity:$('reqCapacity').value||'0'});[...$('reqFacilities').selectedOptions].forEach(o=>p.append('facilities[]',o.value));if(S.request){p.set('source_type',S.request.source_type);p.set('record_id',S.request.id)}return p}
function payload(action){return{action,source_type:S.request?.source_type,record_id:S.request?.id,room_id:S.room?.id,date:$('reqDate').value,start:$('reqStart').value,end:$('reqEnd').value,building:$('reqBuilding').value,room_type:$('reqType').value,capacity:+$('reqCapacity').value||0,facilities:[...$('reqFacilities').selectedOptions].map(o=>o.value)}}
async function searchRooms(){if(!$('reqDate').value||!$('reqStart').value||!$('reqEnd').value)return alertMsg('Date, start time, and end time are required.');try{const d=await api(API+'?'+params());S.criteria=d.criteria;S.results=d.results;S.room=null;S.validation=null;$('resultBanner').innerHTML=`<i class="ti ti-circle-check me-1"></i><b>${d.summary.compatible}</b> compatible room(s) found from ${d.summary.total} filtered room(s).`;$('criteriaSummary').textContent=`${fmtDate(d.criteria.date)} (${d.criteria.day}) · ${d.criteria.start}–${d.criteria.end} · ${d.criteria.capacity} seats`;$('roomRows').innerHTML=d.results.length?d.results.map(r=>`<tr><td><b>${esc(r.room_code)}</b></td><td>${esc(r.building||'—')}</td><td>${esc(r.room_type)}</td><td>${r.capacity}</td><td>${r.facilities.length?esc(r.facilities.join(', ')):'<span class="text-muted">Not configured</span>'}</td><td>${badge(r.state)}</td><td><button class="btn btn-sm btn-outline-primary me-1" data-view-room="${r.id}"><i class="ti ti-eye"></i> View</button><button class="btn btn-sm btn-primary" data-use-room="${r.id}" ${r.compatible?'':'disabled'}><i class="ti ti-check"></i> Select</button></td></tr>`).join(''):`<tr><td colspan="7" class="rac-empty"><i class="ti ti-building-off d-block fs-3 mb-2"></i>No rooms match all configured requirements.</td></tr>`;unlock(3)}catch(e){alertMsg(e.message)}}
async function roomDetail(id){try{const p=params('room');p.set('room_id',id);const d=await api(API+'?'+p);S.room=d.room;$('detailCode').textContent=d.room.room_code;$('detailState').innerHTML=`${d.room.building||'Building not configured'} · ${d.room.state}`;$('roomDetails').innerHTML=dl([['Room type',d.room.room_type],['Building',d.room.building],['Capacity',d.room.capacity+' seats'],['Facilities',d.room.facilities.join(', ')||'Not configured'],['Current status',badge(d.room.state),true],['Suitability',d.room.compatible?'Matches requirements':'Requires correction']]);$('dailyLabel').textContent=`${fmtDate(d.criteria.date)} · ${d.criteria.day}`;$('dailySchedule').innerHTML=d.daily_schedule.length?d.daily_schedule.map(x=>`<div class="rac-time busy"><b>${esc(x.start_time)}–${esc(x.end_time)}</b><div><b>${esc(x.subject_code)} · ${esc(x.section_code)}</b><p>${esc(x.source_type)} · ${esc(x.faculty_name||'Faculty unassigned')} · ${esc(x.status)}</p></div></div>`).join(''):'<div class="rac-time"><b>All day</b><div><b>No recorded use</b><p>This room has no schedule entries for the selected date.</p></div></div>';$('selectRoom').disabled=!d.room.compatible;unlock(4)}catch(e){alertMsg(e.message)}}
async function validateRoom(){if(!S.request){alertMsg('Choose a scheduling request before validating an assignment.');go(1);return}try{const d=await api(API,{method:'POST',body:JSON.stringify(payload('validate'))});S.room=d.room;S.validation=d.validation;$('validateRoomLabel').textContent=`${d.room.room_code} · ${d.criteria.day} ${d.criteria.start}–${d.criteria.end}`;$('validationChecks').innerHTML=d.validation.checks.map(c=>`<div class="rac-check ${c.passed?'pass':'fail'}"><i class="ti ti-${c.passed?'check':'x'}"></i><div><b>${esc(c.label)}</b><small>${esc(c.detail)}</small></div>${badge(c.passed?'Passed':'Failed')}</div>`).join('');$('validationResult').className='rac-validation-result '+(d.validation.valid?'pass':'fail');$('validationResult').innerHTML=d.validation.valid?'<i class="ti ti-shield-check"></i><h3>Validation Passed</h3><p>The selected room meets all current requirements.</p>':'<i class="ti ti-shield-x"></i><h3>Validation Failed</h3><p>Review the exact reason, choose another room, and recheck.</p>';$('continueAssign').disabled=!d.validation.valid;unlock(5)}catch(e){alertMsg(e.message)}}
function renderAssignment(){if(!S.request||!S.room)return;$('assignmentSummary').innerHTML=dl([['Schedule type',S.request.schedule_type],['Subject',S.request.title],['Section',S.request.section_code],['Faculty',S.request.faculty_name||'Unassigned'],['Date / day',fmtDate(S.criteria.date)+' · '+S.criteria.day],['Time',S.criteria.start+'–'+S.criteria.end],['Selected room',S.room.room_code+' · '+S.room.room_type],['Capacity',S.room.capacity+' / '+S.criteria.capacity],['Validation',badge('Passed'),true]])}
async function assign(){const b=$('confirmRoom'),old=b.innerHTML;b.disabled=true;b.innerHTML='<i class="ti ti-loader-2 ti-spin me-1"></i>Final Recheck…';try{const d=await api(API,{method:'POST',body:JSON.stringify(payload('assign'))});S.assignment=d.assignment;S.criteria=d.criteria;S.room=d.room;$('savedSummary').innerHTML=dl([['Schedule type',d.assignment.schedule_type],['Subject',d.assignment.title],['Section',d.assignment.section_code],['Faculty',d.assignment.faculty_name||'Unassigned'],['Day / date',d.assignment.schedule_date?fmtDate(d.assignment.schedule_date):d.assignment.day_of_week],['Time',d.assignment.start_time+'–'+d.assignment.end_time],['Selected room',d.room.room_code],['Capacity match',d.room.capacity+' / '+d.criteria.capacity],['Status',badge(d.assignment.status),true]]);$('goConflict').href=BASE+'/modules/scheduling/pages/conflict-checker.php?source_type='+encodeURIComponent(d.assignment.source_type)+'&record_id='+d.assignment.id;const src={Regular:'teacher-schedule-mapping.php',Special:'special-class-scheduler.php',Exam:'exam-timetable-generator.php'}[d.assignment.source_type];$('returnSource').href=BASE+'/modules/scheduling/pages/'+src+'?record_id='+d.assignment.id;unlock(7)}catch(e){alertMsg(e.message)}finally{b.disabled=false;b.innerHTML=old}}
function exportCsv(){const q=v=>'"'+String(v??'').replace(/"/g,'""')+'"',rows=[['Room','Building','Type','Capacity','Facilities','Status'],...S.results.map(r=>[r.room_code,r.building,r.room_type,r.capacity,r.facilities.join('; '),r.state])];const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([rows.map(r=>r.map(q).join(',')).join('\n')],{type:'text/csv'}));a.download='room-availability.csv';a.click();URL.revokeObjectURL(a.href)}
function showHistory(){const h=S.data.history||[];$('historyBody').innerHTML=h.length?h.map(x=>`<div class="rac-activity-item"><b>${esc(x.assigned_room)} · ${esc(x.source_type)} #${x.source_record_id}</b><p>${x.previous_room?'Replaced '+esc(x.previous_room):'Initial room assignment'} by ${esc(x.assigned_by)}</p><small>${esc(x.assigned_at)}</small></div>`).join(''):'<div class="rac-empty">No room assignment history yet.</div>';$('historyOverlay').classList.remove('d-none')}
async function dashboard(){try{const p=new URLSearchParams({action:'dashboard',date:$('dashDate').value||new Date().toISOString().slice(0,10),academic_year:$('dashYear').value,semester:$('dashSemester').value});const d=await api(API+'?'+p);if(!S.data){S.data=d;fillOptions()}else{S.data={...S.data,...d,options:S.data.options}}renderMetrics(d.summary);renderRequests();renderRecent()}catch(e){alertMsg(e.message)}}
document.addEventListener('click',e=>{const goBtn=e.target.closest('[data-go]');if(goBtn)go(+goBtn.dataset.go);const back=e.target.closest('[data-back]');if(back)go(+back.dataset.back);const rq=e.target.closest('[data-request]');if(rq){const [t,id]=rq.dataset.request.split(':');chooseRequest(S.data.requests.find(x=>x.source_type===t&&+x.id===+id))}const view=e.target.closest('[data-view-room]');if(view)roomDetail(+view.dataset.viewRoom);const use=e.target.closest('[data-use-room]');if(use){S.room=S.results.find(x=>x.id===+use.dataset.useRoom);validateRoom()}});
document.addEventListener('DOMContentLoaded',async()=>{$('dashDate').value=new Date().toISOString().slice(0,10);$('reqDate').value=new Date().toISOString().slice(0,10);$('reqDay').value=new Date().toLocaleDateString('en-US',{weekday:'long'});$('reqStart').value='07:00';$('reqEnd').value='08:30';await dashboard();if(PREFILL.type&&PREFILL.id){const r=S.data.requests.find(x=>x.source_type.toLowerCase()===PREFILL.type.toLowerCase()&&+x.id===+PREFILL.id);if(r)chooseRequest(r)}});
$('reqDate').onchange=()=>{$('reqDay').value=new Date($('reqDate').value+'T00:00:00').toLocaleDateString('en-US',{weekday:'long'})};$('dashApply').onclick=dashboard;$('dashType').onchange=renderRequests;$('manualSearch').onclick=manual;$('changeRequest').onclick=()=>go(1);$('findRooms').onclick=searchRooms;$('selectRoom').onclick=validateRoom;$('recheckRoom').onclick=validateRoom;$('continueAssign').onclick=()=>{renderAssignment();unlock(6)};$('confirmRoom').onclick=assign;$('exportRooms').onclick=exportCsv;$('racPrintBtn').onclick=()=>print();$('printAssignment').onclick=()=>print();$('assignAnother').onclick=()=>location.reload();$('racHistoryBtn').onclick=showHistory;$('closeHistory').onclick=()=>$('historyOverlay').classList.add('d-none');$('historyOverlay').onclick=e=>{if(e.target===$('historyOverlay'))$('historyOverlay').classList.add('d-none')};$('resetRequirements').onclick=()=>{$('reqBuilding').value='';$('reqType').value='';$('reqCapacity').value=S.request?.participant_count||0;[...$('reqFacilities').options].forEach(o=>o.selected=false)};
})();
</script>
